"""Generate tests/fixtures/yake_parity.rs from the yake package.

Run from the repository root:

    uv run --python 3.12 --with yake==0.7.3 \
      python -I tests/fixtures/yake_parity.py tests/fixtures/yake_parity.rs

For each text, the fixture records the sentences and tokens yake's segtok
segmentation produced, the words of the text that are in yake's English
stopword list (also after yake drops a final "s"), and two rankings with
the default n = 3 and window 1:
- "all": every valid candidate with its score (dedup_lim = 1.0);
- "levs": the top 10 after Levenshtein deduplication at 0.9.
"""

import importlib.metadata
import json
import sys

import yake
from yake.data import DataCore

TEXTS = {
    "satellites": (
        "The European Space Agency launched two Sentinel satellites in 2014. "
        "Each Sentinel satellite carries a radar instrument that maps sea ice, "
        "and the ESA ground segment in Frascati processes 1,500 images per day. "
        "Radar images of sea ice help ships plan routes through the Arctic. "
        "The Sentinel programme of the European Union funds the satellites."
    ),
    "databases": (
        "Column stores keep each column of a table in its own file. "
        "Analytical queries read few columns, so column stores read less data "
        "than row stores. Compression of sorted columns saves space, and "
        "vectorized execution of queries uses the CPU cache well. "
        "PostgreSQL is a row store; DuckDB is a column store."
    ),
    "bees": (
        "Honey bees communicate the location of food with the waggle dance. "
        "The angle of the dance encodes the direction of the food source "
        "relative to the sun, and the duration of the waggle run encodes the "
        "distance. Karl von Frisch decoded the waggle dance in the 1940s."
    ),
}


def rust_str(s):
    return json.dumps(s, ensure_ascii=False)


def rust_f64(x):
    r = repr(float(x))
    return r if any(ch in r for ch in ".eE") else r + ".0"


def main(out_path):
    stoplist = yake.KeywordExtractor(lan="en").stopword_set
    cases = []
    for name, text in TEXTS.items():
        dc = DataCore(text=text, stopword_set=stoplist, config={"windows_size": 1, "n": 3})
        sentences = dc.sentences_str
        words = {w.lower() for s in sentences for w in s}
        words |= {w[:-1] for w in words if w.endswith("s") and len(w) > 3}
        stopwords = sorted(words & stoplist)
        everything = yake.KeywordExtractor(lan="en", dedup_lim=1.0, top=10**6)
        levs = yake.KeywordExtractor(lan="en", dedup_lim=0.9, dedup_func="levs", top=10)
        rankings = {
            "all": everything.extract_keywords(text),
            "levs": [(k.lower(), h) for k, h in levs.extract_keywords(text)],
        }
        cases.append((name, sentences, stopwords, rankings))

    version = importlib.metadata.version("yake")
    lines = [
        f"// @generated by tests/fixtures/yake_parity.py from yake {version}; do not edit.",
        "",
        "pub struct Case {",
        "    pub name: &'static str,",
        "    pub sentences: &'static [&'static [&'static str]],",
        "    pub stopwords: &'static [&'static str],",
        "    pub rankings: &'static [(&'static str, &'static [(&'static str, f64)])],",
        "}",
        "",
        "pub const CASES: &[Case] = &[",
    ]
    for name, sentences, stopwords, rankings in cases:
        lines.append("    Case {")
        lines.append(f"        name: {rust_str(name)},")
        lines.append("        sentences: &[")
        for s in sentences:
            lines.append("            &[" + ", ".join(rust_str(w) for w in s) + "],")
        lines.append("        ],")
        lines.append(
            "        stopwords: &[" + ", ".join(rust_str(w) for w in stopwords) + "],"
        )
        lines.append("        rankings: &[")
        for m, ranked in rankings.items():
            lines.append(f"            ({rust_str(m)}, &[")
            for p, s in ranked:
                lines.append(f"                ({rust_str(p)}, {rust_f64(s)}),")
            lines.append("            ]),")
        lines.append("        ],")
        lines.append("    },")
    lines.append("];")
    with open(out_path, "w") as f:
        f.write("\n".join(lines) + "\n")


if __name__ == "__main__":
    main(sys.argv[1])
